using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud05{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;JObject R(Component c){var r=(RectTransform)c.transform;return new JObject{{"path",P(r)},{"anchorMin",r.anchorMin.ToString()},{"anchorMax",r.anchorMax.ToString()},{"offsetMin",r.offsetMin.ToString()},{"offsetMax",r.offsetMax.ToString()},{"size",r.rect.size.ToString()}};}var data=new JObject{{"texts",new JArray(h.Texts.Select(t=>new JObject{{"id",t.Id},{"text",t.View.text},{"rect",R(t.View)}}))},{"buttons",new JArray(h.Buttons.Select(b=>new JObject{{"id",b.Id},{"rect",R(b.View)}}))},{"sections",new JArray(h.Sections.Select(s=>new JObject{{"id",s.Id},{"path",P(s.Body.transform)}}))},{"catalog",new JArray(h.Catalog.Select((c,i)=>new JObject{{"i",i},{"id",c.Definition?.Id},{"name",c.Definition?.DisplayName},{"tool",c.Tool.ToString()},{"category",c.Category.ToString()},{"rect",R(c.View)}}))},{"rail",new JArray(h.Sandbox.RailwayHud.Commands.Select(c=>new JObject{{"id",c.Command},{"rect",R(c.Button)}}))}};File.WriteAllText("Docs/Measurements/2026-10-02-hud-05/inventory.json",data.ToString());return "Saved current authored UI inventory";}}
